        "சிறுபாணாற்றுப்படை 269 அடிகளைக் கொண்டது; ஆசிரியர் இடைக்கழிநாட்டு நல்லூர் நத்தத்தனார்; பாட்டுடைத் தலைவன் ஓய்மாநாட்டு நல்லியக்கோடன்.",
